623	    /// up the internal state necessary to start it later.
624	    pub fn init(gpa: Allocator, cfg: Config) !Subprocess {
625	        // We have a lot of maybe-allocations that all share the same lifetime
626	        // so use an arena so we don't end up in an accounting nightmare.
627	        var arena = std.heap.ArenaAllocator.init(gpa);
628	        errdefer arena.deinit();
629	        const alloc = arena.allocator();
630	
631	        // Get our env. If a default env isn't provided by the caller
632	        // then we get it ourselves.
633	        var env = cfg.env;
634	        errdefer env.deinit();
635	
636	        // If we have a resources dir then set our env var
637	        if (cfg.resources_dir) |dir| {
638	            log.info("found Ghostty resources dir: {s}", .{dir});
639	            try env.put("GHOSTTY_RESOURCES_DIR", dir);
640	        }
641	
642	        // Set our TERM var. This is a bit complicated because we want to use
643	        // the ghostty TERM value but we want to only do that if we have
644	        // ghostty in the TERMINFO database.
645	        //
646	        // For now, we just look up a bundled dir but in the future we should
647	        // also load the terminfo database and look for it.
648	        if (cfg.resources_dir) |base| {
649	            try env.put("TERM", cfg.term);
650	            try env.put("COLORTERM", "truecolor");
651	
652	            // Assume that the resources directory is adjacent to the terminfo
653	            // database
654	            var buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
655	            const dir = try std.mem.print(&buf, "{s}/terminfo", .{
656	                std.fs.path.dirname(base) orelse unreachable,
657	            });
658	            try env.put("TERMINFO", dir);
659	        } else {
660	            if (comptime builtin.target.os.tag.isDarwin()) {
661	                log.warn("ghostty terminfo not found, using xterm-256color", .{});
662	                log.warn("the terminfo SHOULD exist on macos, please ensure", .{});
663	                log.warn("you're using a valid app bundle.", .{});
664	            }
665	
666	            try env.put("TERM", "xterm-256color");
667	            try env.put("COLORTERM", "truecolor");
668	        }
669	
670	        // Add our binary to the path if we can find it.
671	        ghostty_path: {
672	            // Skip this for flatpak since host cannot reach them
673	            if ((comptime build_config.flatpak) and
674	                internal_os.isFlatpak())
675	            {
676	                break :ghostty_path;
677	            }
678	
679	            var exe_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
680	            const exe_bin_path = exe_buf[0 .. std.process.executablePath(
681	                global.io(),
682	                &exe_buf,
683	            ) catch |err| {
684	                log.warn("failed to get ghostty exe path err={}", .{err});
685	                break :ghostty_path;
686	            }];
687	            const exe_dir = std.fs.path.dirname(exe_bin_path) orelse break :ghostty_path;
688	            log.debug("appending ghostty bin to path dir={s}", .{exe_dir});
689	
690	            // We always set this so that if the shell overwrites the path
691	            // scripts still have a way to find the Ghostty binary when
692	            // running in Ghostty.
693	            try env.put("GHOSTTY_BIN_DIR", exe_dir);
694	
695	            // Append if we have a path. We want to append so that ghostty is
696	            // the last priority in the path. If we don't have a path set
697	            // then we just set it to the directory of the binary.
698	            if (env.get("PATH")) |path| {
699	                // Verify that our path doesn't already contain this entry
700	                var it = std.mem.tokenizeScalar(u8, path, std.fs.path.delimiter);
701	                while (it.next()) |entry| {
702	                    if (std.mem.eql(u8, entry, exe_dir)) break :ghostty_path;
703	                }
704	
705	                try env.put(
706	                    "PATH",
707	                    try appendEnv(alloc, path, exe_dir),
708	                );
709	            } else {
710	                try env.put("PATH", exe_dir);
711	            }
712	        }
713	
714	        // On macOS, export additional data directories from our
715	        // application bundle.
716	        if (comptime builtin.target.os.tag.isDarwin()) darwin: {
717	            const resources_dir = cfg.resources_dir orelse break :darwin;
718	
719	            var buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
720	
721	            const xdg_data_dir_key = "XDG_DATA_DIRS";
722	            if (std.mem.print(&buf, "{s}/..", .{resources_dir})) |data_dir| {
723	                try env.put(
724	                    xdg_data_dir_key,
725	                    try appendEnv(
726	                        alloc,
727	                        env.get(xdg_data_dir_key) orelse "/usr/local/share:/usr/share",
728	                        data_dir,
729	                    ),
730	                );
731	            } else |err| {
732	                log.warn("error building {s}; err={}", .{ xdg_data_dir_key, err });
733	            }
734	
735	            const manpath_key = "MANPATH";
736	            if (std.mem.print(&buf, "{s}/../man", .{resources_dir})) |man_dir| {
737	                // Always append with colon in front, as it mean that if
738	                // `MANPATH` is empty, then it should be treated as an extra
739	                // path instead of overriding all paths set by OS.
740	                try env.put(
741	                    manpath_key,
742	                    try appendEnvAlways(
743	                        alloc,
744	                        env.get(manpath_key) orelse "",
745	                        man_dir,
746	                    ),
747	                );
748	            } else |err| {
749	                log.warn("error building {s}; man pages may not be available; err={}", .{ manpath_key, err });
750	            }
751	        }
752	
753	        // Set environment variables used by some programs (such as neovim) to detect
754	        // which terminal emulator and version they're running under.
755	        try env.put("TERM_PROGRAM", "ghostty");
756	        try env.put("TERM_PROGRAM_VERSION", build_config.version_string);
757	
758	        // VTE_VERSION is set by gnome-terminal and other VTE-based terminals.
759	        // We don't want our child processes to think we're running under VTE.
760	        // This is not apprt-specific, so we do it here.
761	        _ = env.orderedRemove("VTE_VERSION");
762	
763	        // Setup our shell integration, if we can.
764	        const shell_command: configpkg.Command = shell: {
765	            const default_shell_command: configpkg.Command =
766	                cfg.command orelse .{ .shell = switch (builtin.target.os.tag) {
767	                    .windows => "cmd.exe",
768	                    else => "sh",
769	                } };
770	
771	            // Always set up shell features (GHOSTTY_SHELL_FEATURES). These are
772	            // used by both automatic and manual shell integrations.
773	            try shell_integration.setupFeatures(
774	                &env,
775	                cfg.shell_integration_features,
776	                cfg.cursor_blink orelse true,
777	            );
778	
779	            const force: ?shell_integration.Shell = switch (cfg.shell_integration) {
780	                .none => {
781	                    // This is a source of confusion for users despite being
782	                    // opt-in since it results in some Ghostty features not
783	                    // working. We always want to log it.
784	                    log.info("shell integration disabled by configuration", .{});
785	                    break :shell default_shell_command;
786	                },
787	
788	                .detect => null,
789	                .bash => .bash,
790	                .elvish => .elvish,
791	                .fish => .fish,
792	                .nushell => .nushell,
793	                .zsh => .zsh,
794	            };
795	
796	            const dir = cfg.resources_dir orelse {
797	                log.warn("no resources dir set, shell integration disabled", .{});
798	                break :shell default_shell_command;
799	            };
800	
801	            const integration = try shell_integration.setup(
802	                alloc,
803	                dir,
804	                default_shell_command,
805	                &env,
806	                force,
807	            ) orelse {
808	                log.warn("shell could not be detected, no automatic shell integration will be injected", .{});
809	                break :shell default_shell_command;
810	            };
811	
812	            log.info(
813	                "shell integration automatically injected shell={}",
814	                .{integration.shell},
815	            );
816	
817	            break :shell integration.command;
818	        };
819	
820	        // Add the environment variables that override any others.
821	        {
822	            var it = cfg.env_override.iterator();
823	            while (it.next()) |entry| try env.put(
824	                entry.key_ptr.*,
825	                entry.value_ptr.*,
826	            );
827	        }
828	
829	        // Build our args list
830	        const args: []const [:0]const u8 = execCommand(
831	            alloc,
832	            shell_command,
833	            internal_os.passwd,
834	        ) catch |err| switch (err) {
835	            // If we fail to allocate space for the command we want to
836	            // execute, we'd still like to try to run something so
837	            // Ghostty can launch (and maybe the user can debug this further).
838	            // Realistically, if you're getting OOM, I think other stuff is
839	            // about to crash, but we can try.
840	            error.OutOfMemory => oom: {

317	fn termiosTimer(
318	    td_: ?*termio.Termio.ThreadData,
319	    _: *xev.Loop,
320	    _: *xev.Completion,
321	    r: xev.Timer.RunError!void,
322	) xev.CallbackAction {
323	    // log.debug("termios timer fired", .{});
324	
325	    // This should never happen because we guard starting our
326	    // timer on windows but we want this assertion to fire if
327	    // we ever do start the timer on windows.
328	    // TODO: support on windows
329	    if (comptime builtin.target.os.tag == .windows) {
330	        @panic("termios timer not implemented on Windows");
331	    }
332	
333	    _ = r catch |err| switch (err) {
334	        // This is sent when our timer is canceled. That's fine.
335	        error.Canceled => return .disarm,
336	
337	        else => {
338	            log.warn("error in termios timer callback err={}", .{err});
339	            @panic("crash in termios timer callback");
340	        },
341	    };
342	
343	    const td = td_.?;
344	    assert(td.backend == .exec);
345	    const exec = &td.backend.exec;
346	
347	    // This is kind of hacky but we rebuild a Pty struct to get the
348	    // termios data.
349	    const mode: ptypkg.Mode = (Pty{
350	        .master = exec.read_thread_fd,
351	        .slave = undefined,
352	    }).getMode() catch |err| err: {
353	        log.warn("error getting termios mode err={}", .{err});
354	
355	        // If we have an error we return the default mode values
356	        // which are the likely values.
357	        break :err .{};
358	    };
359	
360	    // If the mode changed, then we process it.
361	    if (!std.meta.eql(mode, exec.termios_mode)) mode_change: {
362	        log.debug("termios change mode={}", .{mode});
363	        exec.termios_mode = mode;
364	
365	        // We assume we're in some sort of password input if we're
366	        // in canonical mode and not echoing. This is a heuristic.
367	        const password_input = mode.canonical and !mode.echo;
368	
369	        // If our password input state changed on the terminal then
370	        // we notify the surface.
371	        {
372	            td.renderer_state.mutex.lockUncancelable(global.io());
373	            defer td.renderer_state.mutex.unlock(global.io());
374	            const t = td.renderer_state.terminal;
375	            if (t.flags.password_input == password_input) {
376	                break :mode_change;
377	            }
378	        }
379	
380	        // We have to notify the surface that we're in password input.
381	        // We must block on this because the balanced true/false state
382	        // of this is critical to apprt behavior.
383	        _ = td.surface_mailbox.push(.{
384	            .password_input = password_input,
385	        }, .{ .forever = {} });
386	    }
387	
388	    // Repeat the timer
389	    if (exec.termios_timer_running) {
390	        exec.termios_timer.run(
391	            td.loop,
392	            &exec.termios_timer_c,
393	            TERMIOS_POLL_MS,
394	            termio.Termio.ThreadData,
395	            td,
396	            termiosTimer,
397	        );
398	    }
399	
400	    return .disarm;
401	}
